import{_ as r,C as a,c,o as l,a3 as n,G as i,j as o,a as t}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Invoice a POS order","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/invoice-a-pos-order.md","filePath":"master/sales/point-of-sale/selling/invoice-a-pos-order.md","lastUpdated":1792041590000}'),d={name:"master/sales/point-of-sale/selling/invoice-a-pos-order.md"};function h(u,e,p,m,g,v){const s=a("ImagePopup");return l(),c("div",null,[e[0]||(e[0]=n('<h1 id="invoice-a-pos-order" tabindex="-1">Invoice a POS order <a class="header-anchor" href="#invoice-a-pos-order" aria-label="Permalink to &quot;Invoice a POS order&quot;">​</a></h1><p>Most till sales need only a receipt. Some customers, such as businesses, need a proper invoice for their records. You can create a customer invoice from a POS order, either while paying or later from the <strong>Orders</strong> page.</p><blockquote><p><strong>In simple words:</strong> Tick Invoice when you pay, or click Invoice on the order afterwards. Aureus creates the invoice for the customer.</p></blockquote><p>An invoice needs a customer on the order. Add one first. See <a href="./order-notes-and-customers.html">Notes and customers</a>.</p><h2 id="invoice-while-paying" tabindex="-1">Invoice while paying <a class="header-anchor" href="#invoice-while-paying" aria-label="Permalink to &quot;Invoice while paying&quot;">​</a></h2><ol><li>Add the customer to the order.</li><li>Click <strong>Payment</strong>.</li><li>Choose the method and enter the amount.</li><li>Tick the <strong>Invoice</strong> checkbox.</li></ol>',6)),i(s,{src:"/images1/pos/payment_invoice_checkbox.png",alt:"Payment screen with customer Sofia Rossi, Cash 7,000 and the Invoice checkbox ticked"}),e[1]||(e[1]=n('<ol start="5"><li>Click <strong>Validate</strong>.</li></ol><p>If there is no customer, the terminal shows &quot;Customer required&quot; and asks you to select one before validating.</p><h2 id="invoice-later-from-the-orders-page" tabindex="-1">Invoice later from the Orders page <a class="header-anchor" href="#invoice-later-from-the-orders-page" aria-label="Permalink to &quot;Invoice later from the Orders page&quot;">​</a></h2><ol><li>Click your initials, then <strong>Orders</strong>.</li><li>Click the paid order, for example <strong>TNE/00001</strong> for Sofia Rossi.</li><li>Click <strong>Invoice</strong>.</li></ol>',4)),i(s,{src:"/images1/pos/invoice_button_orders.png",alt:"Terminal Orders page with order TNE/00001 selected and the Invoice button under the lines"}),e[2]||(e[2]=o("ol",{start:"4"},[o("li",null,[t('In the window "Create an invoice for this order?", click '),o("strong",null,"Confirm"),t(".")])],-1)),i(s,{src:"/images1/pos/invoice_confirm_window.png",alt:"Window titled Create an invoice for this order with Cancel and Confirm buttons"}),e[3]||(e[3]=o("p",null,[t("A notice says "),o("strong",null,"Invoice created"),t(". The order status changes to "),o("strong",null,"Invoiced"),t(" and the "),o("strong",null,"Invoice"),t(" button turns grey.")],-1)),i(s,{src:"/images1/pos/invoice_created_status.png",alt:"Orders list with TNE/00001 showing the status Invoiced and the Invoice button disabled"}),e[4]||(e[4]=n('<h2 id="find-the-invoice" tabindex="-1">Find the invoice <a class="header-anchor" href="#find-the-invoice" aria-label="Permalink to &quot;Find the invoice&quot;">​</a></h2><p>The invoice is a normal customer invoice. Go to <code>Invoices → Customers → Invoices</code> or <code>Accounting → Customers → Invoices</code>. For TechNest the invoice is <strong>INV/2026/00004</strong>, status <strong>Posted</strong>, customer <strong>Sofia Rossi</strong>, amount 6,597.</p>',2)),i(s,{src:"/images1/pos/invoice_in_invoices_list.png",alt:"Invoices list with INV/2026/00004 for Sofia Rossi, Posted, 6,597"}),e[5]||(e[5]=n('<p>Open it to see the same lines as the order, with the order number as the <strong>Source Document</strong>. From there you can send it or register more payments like any invoice. See <a href="./../../../finance/customer-invoices/">Invoicing processes</a> and <a href="./../../../finance/customer-invoices/create-invoice.html">Create an invoice</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Invoice:</strong> Creates the invoice once. If the order already has one, you get the same invoice.</li><li><strong>Invoiced:</strong> The order status after the invoice exists.</li><li>After the session closes, an invoiced order settles through the customer invoice instead of the closing entry of the session.</li></ul><p>An order cannot be invoiced after its session is closed. The invoice journal must also be set in the register. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Not sure if a customer wants an invoice? Ask before payment. It is faster to tick <strong>Invoice</strong> than to find the order later.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Invoice the order in the session it was sold in. Once the session is <strong>Closed &amp; Posted</strong>, you can no longer invoice it from the terminal.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./pay-and-receipt.html">Pay and receipt</a></li><li><a href="./refunds.html">Refunds</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li></ul>',8))])}const I=r(d,[["render",h]]);export{_ as __pageData,I as default};
